// --- Cobertura ---
function jgMediaIntl(m){ let cov=[]; try{ cov=(typeof mediaCoverage==="function")?mediaCoverage(m):(m.coverage||[]); }catch(e){} if(!cov.length) return true; return cov.some(e=>{ const x=normLoose(e); return x==="internacional"||x==="mundial"||x==="global"; }); }
function jgMediaLocal(m, countryName){
  let cov=[]; try{ cov=(typeof mediaCoverage==="function")?mediaCoverage(m):(m.coverage||[]); }catch(e){} if(!cov.length) return false;
  const target=normLoose(countryName);
  const country=(DB.countries||[]).find(c=>normLoose(c.commonName)===target||normLoose(c.officialName||"")===target);
  const names=new Set([target]); if(country&&country.officialName) names.add(normLoose(country.officialName));
  try{ if(typeof MEDIA_COUNTRY_ALIAS==="object"&&MEDIA_COUNTRY_ALIAS[target]) names.add(normLoose(MEDIA_COUNTRY_ALIAS[target])); }catch(e){}
  const conf=country?normLoose(country.conf||""):"";
  let regions=null; try{ const R=(typeof getRegions==="function")?getRegions():null; if(R){ regions=Object.create(null); Object.keys(R).forEach(k=>{ regions[normLoose(k)]=new Set((R[k]||[]).map(normLoose)); }); } }catch(e){}
  let confByLabel=null; try{ if(typeof CONFEDERATION_LABELS==="object"&&CONFEDERATION_LABELS){ confByLabel=Object.create(null); Object.keys(CONFEDERATION_LABELS).forEach(k=>{ confByLabel[normLoose(CONFEDERATION_LABELS[k])]=normLoose(k); }); } }catch(e){}
  for(const raw of cov){ const e=normLoose(raw); if(!e) continue; if(e==="internacional"||e==="mundial"||e==="global") continue; if(names.has(e)) return true; if(regions&&regions[e]){ for(const nm of names){ if(regions[e].has(nm)) return true; } } if(conf&&(e===conf||(confByLabel&&confByLabel[e]===conf))) return true; }
  return false;
}
function jgNewsBuckets(){
  const t=team(); const tC=teamName(t);
  let rivals=[]; try{ if(typeof teamsInGroup==="function"&&t&&t.group) rivals=teamsInGroup(t.group).filter(x=>x.id!==t.id); }catch(e){}
  const rivalC=rivals.map(x=>teamName(x));
  const media=newsMediaPool();
  const local=[], intl=[], rival=[];
  media.forEach(m=>{
    if(jgMediaLocal(m,tC)){ local.push(m); return; }
    if(rivalC.some(rc=>jgMediaLocal(m,rc))){ rival.push(m); return; }
    intl.push(m);
  });
  let teams=[t].concat(rivals);
  try{ (DB.teams||[]).filter(x=>/^[A-L]$/.test((x.group||"").trim())).sort((a,b)=>(b.fifaPoints||0)-(a.fifaPoints||0)).slice(0,8).forEach(x=>{ if(!teams.some(y=>y&&y.id===x.id)) teams.push(x); }); }catch(e){}
  // Organismos: torneo, FIFA y confederaciones (para las cuentas de X).
  let confs=[]; try{ if(DB.confederations){ confs=Object.keys(DB.confederations).map(k=>Object.assign({__conf:k}, DB.confederations[k])); } }catch(e){}
  const fifa=DB.fifa||null, event=DB.event||null;
  return { local, intl, rival, teams:teams.filter(Boolean), t, rivals, confs, fifa, event };
}
// Factor de actualidad: la importancia editorial no desaparece de golpe, pierde peso con el tiempo.
function newsFreshFactor(min){ const h=min/60; if(h<1) return 1.00; if(h<3) return 0.95; if(h<6) return 0.85; if(h<12) return 0.70; if(h<24) return 0.45; if(h<48) return 0.20; return 0.05; }
// Interleave ponderado (largest-remainder) sobre una lista de buckets {name,w,arr,kind}.
function jgFeedSeq(n, buckets){
  buckets=(buckets||[]).filter(x=>x.arr && x.arr.length);
  if(!buckets.length) return [];
  const tw=buckets.reduce((s,x)=>s+x.w,0)||1; buckets.forEach(x=>x.w/=tw);
  const taken=buckets.map(()=>0), idx=buckets.map(()=>0), seq=[];
  for(let i=0;i<n;i++){
    let best=0, bestScore=Infinity;
    for(let j=0;j<buckets.length;j++){ const target=buckets[j].w*(i+1); const score=taken[j]-target; if(score<bestScore){ bestScore=score; best=j; } }
    const bk=buckets[best]; const e=bk.arr[idx[best]%bk.arr.length]; idx[best]++; taken[best]++;
    seq.push({kind:bk.kind, e, bucket:bk.name});
  }
  return seq;
}
