// ¿La entidad tiene un perfil de redes configurado? (nombre de perfil o usuario).
function jgHasSocial(e){ return !!(((e&&e.socialProfileName)||"").toString().trim() || ((e&&e.socialUsername)||"").toString().trim()); }
// Resuelve el perfil de redes real de una entidad (medio: usa mediaSocialProfile con la cobertura que aplica).
function jgSocialResolve(it, ctx){
  if(!it||!it.e) return it&&it.e||{};
  // Selecciones y organismos (torneo/FIFA/confederación) llevan sus campos sociales directamente.
  if(it.kind!=="media") return it.e;
  const m=it.e;
  let cov=null;
  if(it.bucket==="local"){ cov=teamName(ctx&&ctx.t); }
  else if(it.bucket==="rival"){ const r=(ctx&&ctx.rivals||[]).find(rr=>jgMediaLocal(m,teamName(rr))); cov=r?teamName(r):null; }
  let prof=null; try{ if(typeof mediaSocialProfile==="function") prof=mediaSocialProfile(m,cov); }catch(e){}
  return prof?Object.assign({},m,prof):m;
}
