try{ window.jgOpenNews=jgOpenNews; window.jgCloseNews=jgCloseNews; }catch(e){}
// Ajusta la pantalla actual (noticias/buzón/inicio) para que llene el alto disponible sin scroll
// de página; el contenido interno (listas, tweets) scrollea por dentro. Angosto = alto natural.
function jgFitScreen(){
  if(!JUEGO) return;
  const id=JUEGO.screen; let el=null;
  if(id==="noticias") el=document.querySelector(".jg-news3");
  else if(id==="buzon") el=document.getElementById("jg-mail");
  else if(id==="inicio") el=document.querySelector(".jg-home");
  if(!el) return;
  if(window.innerWidth<=1080){ el.style.height=""; return; }
  el.style.height="auto";
  const rect=el.getBoundingClientRect();
  let h=window.innerHeight - rect.top - 14;
  el.style.height = Math.max(340, Math.round(h))+"px";
  // Segundo pase: descuenta cualquier overflow residual de página (padding de ancestros).
  try{ const doc=document.documentElement; const over=doc.scrollHeight - doc.clientHeight; if(over>0){ h=h-over; el.style.height=Math.max(340, Math.round(h))+"px"; } }catch(e){}
}
function jgFitNews(){ jgFitScreen(); }
var jgFitBound=false;
function jgBindFit(){ if(jgFitBound) return; jgFitBound=true; try{ window.addEventListener("resize",()=>{ const s=JUEGO&&JUEGO.screen; if(s==="noticias"||s==="buzon"||s==="inicio") jgFitScreen(); }); }catch(e){} }
// --- Rotación de la noticia principal (pausa al pasar el cursor; líneas clicables) ---
var jgMainTimer=null, jgMainCtl=null;
function jgMainStop(){ if(jgMainTimer){ clearInterval(jgMainTimer); jgMainTimer=null; } jgMainCtl=null; }
function jgMainStart(){
  jgMainStop();
  const main=document.getElementById("jg-nmain"); if(!main) return;
  const slides=[...main.querySelectorAll(".jg-nslide")], lines=[...main.querySelectorAll(".jg-nline")];
  if(slides.length<=1) return;
  let idx=0, paused=false;
  const show=k=>{ idx=((k%slides.length)+slides.length)%slides.length; slides.forEach((s,i)=>s.classList.toggle("on",i===idx)); lines.forEach((d,i)=>d.classList.toggle("on",i===idx)); };
  const arm=()=>{ if(jgMainTimer) clearInterval(jgMainTimer); jgMainTimer=setInterval(()=>{ if(!paused) show(idx+1); },5000); };
  lines.forEach(d=>d.addEventListener("click",ev=>{ ev.stopPropagation(); show(+d.dataset.nline); arm(); }));
  main.addEventListener("mouseenter",()=>{ paused=true; });
  main.addEventListener("mouseleave",()=>{ paused=false; });
  // Expuesto para navegar con las flechas ← →.
  jgMainCtl={ next:()=>{ show(idx+1); arm(); }, prev:()=>{ show(idx-1); arm(); } };
  jgBindArrowKeys();
  show(0); arm();
}
// Navegación por correos del Buzón con ← → (selecciona el anterior/siguiente y lo marca leído).
function jgMailNav(delta){
  const box=document.getElementById("jg-mlist"); if(!box) return;
  const btns=[...box.querySelectorAll(".jg-mli")]; if(!btns.length) return;
  let cur=btns.findIndex(b=>b.classList.contains("sel")); if(cur<0) cur=0;
  let ni=cur+delta; if(ni<0) ni=0; if(ni>=btns.length) ni=btns.length-1;
  if(ni===cur) return;
  btns[ni].click();
  try{ btns[ni].scrollIntoView({block:"nearest"}); }catch(e){}
}
// Flechas ← → cambian la noticia principal (Noticias) o el correo (Buzón) sin interferir al escribir.
var jgArrowKeysBound=false;
function jgBindArrowKeys(){
  if(jgArrowKeysBound) return; jgArrowKeysBound=true;
  try{ window.addEventListener("keydown",(e)=>{
    if(!(JUEGO && JUEGO.active)) return;
    if(e.key!=="ArrowLeft" && e.key!=="ArrowRight") return;
    if(e.altKey||e.ctrlKey||e.metaKey) return; // no interferir con atajos del navegador (historial)
    const t=e.target, tag=t&&t.tagName;
    if(t&&(tag==="INPUT"||tag==="TEXTAREA"||tag==="SELECT"||t.isContentEditable)) return;
    if(document.querySelector(".dl-ac-open, .datalist-open")) return; // autocompletado abierto
    const dir=(e.key==="ArrowRight")?1:-1;
    if(JUEGO.screen==="noticias" && jgMainCtl){ e.preventDefault(); dir>0?jgMainCtl.next():jgMainCtl.prev(); }
    else if(JUEGO.screen==="buzon"){ e.preventDefault(); jgMailNav(dir); }
  }); }catch(err){}
}
function scrNoticias(){
  const feed=jgNewsFeed(); const tws=jgTweetsFeed();
  // Evita titulares repetidos entre las tarjetas visibles (los medios comparten plantillas).
  const seenHead=new Set(); const usedId=new Set();
  const take=(arr,n)=>{ const out=[]; for(const it of arr){ if(out.length>=n) break; if(usedId.has(it.id)||seenHead.has(it.head)) continue; out.push(it); usedId.add(it.id); seenHead.add(it.head); } return out; };
  // 1) Destacadas: las 3 de mayor SCORE (importancia × factor de actualidad).
  const byScore=[...feed].sort((a,b)=> (b.score-a.score) || (a.ageMin-b.ageMin));
  const main=take(byScore,3);
  // 2) Actualidad: las 2 más recientes de lo que queda.
  const byRecency=[...feed].sort((a,b)=> a.ageMin-b.ageMin);
  const side=take(byRecency,2);
  // 3) Últimas noticias: todas las de las últimas 72 h, en orden cronológico (con scroll interno).
  const recent72=byRecency.filter(it=>it.ageMin<=72*60);
  const list=take(recent72,99);
  return `<div class="jg-buztitle">Noticias</div>`+
  `<div class="jg-news3">
    <div class="jg-newscol2">
      ${jgNewsMainHTML(main)}
      <div class="jg-nside-row">${side.map(jgNewsSideHTML).join("")}</div>
      <div class="jg-nlist">${list.map(jgNewsRowHTML).join("")}</div>
    </div>
    <div class="jg-twcol2"><div class="jg-twhead"><span style="font-family:'Space Grotesk';font-weight:800;">𝕏</span> En redes</div><div class="jg-twscroll">${tws.map(tweetHTML).join("")}</div></div>
  </div>`;
}
