// ===== Estado físico/mental (condición, ritmo, moral): valores random por partida =====
// Color de un valor 0–100 en la escala rojo(0)→amarillo(50)→verde(100).
function statusColor(v){ v=(v==null)?50:Math.max(0,Math.min(100,v)); return `hsl(${Math.round(v*1.2)},68%,45%)`; }
function statusDot(v){ return `<span class="stat-dot" style="background:${statusColor(v)};" title="${v==null?"–":Math.round(v)}"></span>`; }
// Genera (una sola vez por partida) la condición/ritmo/moral de un jugador si aún no existen.
function ensurePlayerStatus(p){
  if(!p) return false;
  const rnd=()=>Math.floor(35+Math.random()*66); // 35–100
  let changed=false;
  if(p.condition==null){ p.condition=rnd(); changed=true; }
  if(p.sharpness==null){ p.sharpness=rnd(); changed=true; }
  if(p.morale==null){ p.morale=rnd(); changed=true; }
  return changed;
}
function ensureSquadStatus(t){
  if(!t) return;
  let changed=false;
  (t.players||[]).forEach(p=>{ if(ensurePlayerStatus(p)) changed=true; });
  if(changed && typeof persist==="function") persist();
}
// Exponer al scope global: la ficha del jugador (funciones/jugadores.js) vive FUERA de este IIFE y
// necesita estos ayudantes para dibujar los círculos de condición/ritmo/moral.
try{ window.statusColor=statusColor; window.statusDot=statusDot; window.ensurePlayerStatus=ensurePlayerStatus; window.ensureSquadStatus=ensureSquadStatus; }catch(e){}

