// Cuerpo técnico: el entrenador principal arriba (foto cuadrada, nombre cliqueable) + tabla de empleados.
function cuerpoStaffHTML(t){
  const coaches=(t.coaches||[]).slice();
  let head0 = JUEGO.coach || coaches.find(c=>normLoose(c.contractRole||"").indexOf("entrenador del primer equipo")===0) || coaches[0] || null;
  const headName = head0 ? (JUEGO.coach && !head0.id ? "Tú · Mánager" : (personCoachName(head0))) : "Tú · Mánager";
  const headRole = (head0 && head0.contractRole) ? head0.contractRole : "Entrenador del primer equipo";
  const headNameHTML = (head0 && head0.id) ? `<span class="jg-lnk2" data-action="open-coach" data-id="${head0.id}">${esc(headName)}</span>` : esc(headName);
  // Empleados = el resto del cuerpo técnico, SIN el entrenador principal (ya está en el rectángulo de arriba).
  const rest = coaches.filter(c=> c!==head0 && normLoose(c.contractRole||"")!=="entrenador del primer equipo");
  const cf = (typeof playerCountryName==="function");
  const empRows = rest.map(c=>{
    const country = cf ? playerCountryName(c) : "";
    const paisHTML = country ? `${(typeof flagIconHTML==="function")?flagIconHTML(country):""}${esc(country)}` : "—";
    return `<tr data-action="open-coach" data-id="${c.id}" style="cursor:pointer;">
      <td style="min-width:160px;white-space:nowrap;"><span class="num-badge coach-role-badge" style="display:inline-flex;width:auto;padding:0 8px;font-size:10px;letter-spacing:.05em;margin-right:8px;vertical-align:middle;">${coachRoleBadge(c.contractRole)}</span>${personPhotoHTML(c,"width:24px;height:24px;border-radius:50%;object-fit:cover;vertical-align:middle;margin-right:8px;")}${playerDisplayNameHTML(c)}</td>
      <td style="white-space:nowrap;">${paisHTML}</td>
      <td class="mono">${playerAge(c)!=null?playerAge(c):"—"}</td>
      <td style="white-space:nowrap;">${c.contractRole?esc(c.contractRole):"—"}</td>
    </tr>`;
  }).join("");
  return `<div class="jg-coach">
    <div class="ph">${coachFaceImg(head0)}</div>
    <div style="flex:1;"><div class="nm">${headNameHTML}</div><div class="rl">${esc(headRole)}</div><div class="mt"><span>Contrato hasta: Copa del Mundo 2026</span></div></div>
    <div style="text-align:center;"><div class="rating" style="font-size:34px;">${head0&&head0.rating!=null?head0.rating:"—"}</div><div style="font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em;">Reputación</div></div>
  </div>
  <div class="card"><div class="section-title" style="margin:0 0 6px;"><h2 style="font-size:15px;">Empleados</h2><span class="hint">${rest.length} miembro${rest.length===1?'':'s'}</span></div>
  ${rest.length?`<div class="tbl-wrap"><table class="pl-table"><thead><tr><th>Empleado</th><th>País</th><th>Edad</th><th>Puesto</th></tr></thead><tbody>${empRows}</tbody></table></div>`:`<p style="font-size:13px;color:var(--muted);margin:6px 0 0;">Aún no hay más empleados registrados para esta selección. Se completará más adelante.</p>`}
  </div>`;
}
// Imagen de un entrenador (foto propia o la silueta genérica del juego, según género). Nunca emoji.
function coachFaceImg(c){
  const has = (c && typeof c.photo==="string" && c.photo.indexOf("data:")===0);
  const src = has ? c.photo : ((typeof personPhotoDefault==="function") ? personPhotoDefault(c) : "");
  return src ? `<img class="${has?'':'is-default'}" src="${src}" alt="">` : "";
}
function personCoachName(c){
  if(!c) return "—";
  if(c.commonName) return c.commonName;
  const fl=((c.firstName||"")+" "+(c.lastName||"")).trim();
  return fl || c.fullName || c.name || c.nombre || c.displayName || "Entrenador";
}

/* Calendario / Entrenamiento — junio 2026 (1 = lunes, 30 días) */
// Rejilla de un mes cualquiera, con los días alineados al día de la semana (lunes primero).
// eventsByDay: { día: [ [claseEvento, texto, tooltip?], … ] }. todayDay: día a resaltar (o null).
function monthGridFor(year, month, eventsByDay, todayDay){
  const dow=["L","M","M","J","V","S","D"];
  let html=dow.map(d=>`<div class="jg-dow">${d}</div>`).join("");
  const daysInMonth=new Date(year, month, 0).getDate();
  const lead=(new Date(year, month-1, 1).getDay()+6)%7; // lunes = 0
  for(let i=0;i<lead;i++) html+=`<div class="jg-cell empty"></div>`;
  for(let day=1;day<=daysInMonth;day++){
    const evs=eventsByDay[day]||[];
    // e[4]===true → e[1] es HTML ya listo (celda enriquecida del calendario); si no, texto escapado.
    html+=`<div class="jg-cell ${day===todayDay?'today':''}"><div class="cd">${day}</div>${evs.map(e=>e[4]?`<div class="jg-ev ${e[0]}"${e[2]?` title="${esc(e[2])}"`:""}>${e[1]}</div>`:`<div class="jg-ev ${e[0]}"${e[2]?` title="${esc(e[2])}"`:""}>${e[3]||""}${esc(e[1])}</div>`).join("")}</div>`;
  }
  return `<div class="jg-cal">${html}</div>`;
}
// Compat: rejilla de junio de 2026 (usada por Entrenamiento), con el día 1 marcado como "hoy".
function monthGrid(eventsByDay){ return monthGridFor(2026, 6, eventsByDay, 1); }
function trainingEvents(){
  const ev={1:[["camp","Concentración"]]};
  for(let d=2;d<=30;d++){ const w=(d-1)%7; ev[d]=[[ (w===5||w===6)?"rest":"train, ", (w===5||w===6)?"Descanso":"Entrenamiento" ]]; }
  // corregir clase
  Object.keys(ev).forEach(d=>{ ev[d]=ev[d].map(e=>{ if(e[0]==="train, ") return ["train",e[1]]; return e; }); });
  return ev;
}
function scrEntrenamiento(){
  return headManageBar("Entrenamiento")+
  `<p class="tab-desc">Calendario de junio de 2026 con las sesiones de entrenamiento de la concentración rumbo al Mundial.</p>
  ${monthGrid(trainingEvents())}
  <div class="jg-legend"><span><i style="background:rgba(52,211,153,.6);"></i>Entrenamiento</span><span><i style="background:rgba(109,99,245,.6);"></i>Concentración</span><span><i style="background:var(--surface-2);border:1px solid var(--line);"></i>Descanso</span></div>`;
}

let calView="lista";
let calMonthIdx=0;
let calSelId=null; // partido seleccionado en la lista (panel de detalle a la derecha)
let _calSelForce=false; // true cuando se abre el calendario para un partido concreto (círculo de forma)
const CAL_MES_LARGO=["Enero","Febrero","Marzo","Abril","Mayo","Junio","Julio","Agosto","Septiembre","Octubre","Noviembre","Diciembre"];
const CAL_GAME_MONTH={y:2026,m:6}; // "mes actual" del juego (la fecha base es 1 jun 2026)
// Meses continuos que abarcan los partidos de la selección (del primero al último), aunque alguno
// intermedio no tenga partido.
function calFixtureMonths(){
  const fx=teamFixtures().filter(f=>f.date && f.date.length>=7);
  if(!fx.length) return [];
  let min=fx[0].date.slice(0,7), max=min;
  fx.forEach(f=>{ const k=f.date.slice(0,7); if(k<min)min=k; if(k>max)max=k; });
  let y=+min.slice(0,4), m=+min.slice(5,7); const ey=+max.slice(0,4), em=+max.slice(5,7);
  const out=[]; let guard=0;
  while((y<ey || (y===ey && m<=em)) && guard++<60){ out.push({y,m}); m++; if(m>12){m=1;y++;} }
  return out;
}
function scrCalendario(){
  // La cuadrícula abre por defecto en el mes actual del juego (junio 2026); si no hay partidos ese mes,
  // en el mes más cercano dentro del rango.
  const months=calFixtureMonths();
  let idx=months.findIndex(mm=>mm.y===CAL_GAME_MONTH.y && mm.m===CAL_GAME_MONTH.m);
  if(idx<0) idx=months.findIndex(mm=>(mm.y>CAL_GAME_MONTH.y)||(mm.y===CAL_GAME_MONTH.y&&mm.m>=CAL_GAME_MONTH.m));
  calMonthIdx = idx>=0?idx:0;
  // NO se reinicia la selección aquí: así, si sales del calendario (p. ej. al abrir un equipo/jugador) y
  // regresas con "atrás", vuelves al MISMO partido que tenías seleccionado. Si aún no hay selección (o el
  // partido ya no existe para esta selección), renderCalBody elige por defecto el próximo partido.
  // El selector Lista/Cuadrícula va DENTRO del rectángulo del equipo, a la derecha (como en Plantilla).
  const seg=`<div class="pl-seg jg-calseg">${[["lista","Lista"],["grid","Cuadrícula"]].map(([v,l])=>`<button class="${calView===v?"on":""}" data-action="cal-view" data-view="${v}">${l}</button>`).join("")}</div>`;
  return headManageBar("Calendario", seg)+`<div id="jg-calbody"></div>`;
}
// Nombre de un jugador por id (para los goles); si no hay id, usa el nombre guardado.
function calPlayerName(g){ if(g && g.playerId){ for(const t of (DB.teams||[])){ const p=(t.players||[]).find(x=>x.id===g.playerId); if(p) return (p.commonName||p.lastName||((p.firstName||"")+" "+(p.lastName||""))).trim(); } } return (g&&g.player)||""; }
// Nombre para las incidencias del partido: forma CORTA (inicial del nombre + apellido, o el nombre
// común si lo tiene) para mostrar, y el nombre COMPLETO para el tooltip al pasar el cursor.
function calIncidentName(e){
  let p=null;
  if(e && e.playerId){ for(const t of (DB.teams||[])){ const q=(t.players||[]).find(x=>x.id===e.playerId); if(q){ p=q; break; } } }
  if(p){
    const common=(p.commonName||"").trim();
    const fn=(p.firstName||"").trim(), ln=(p.lastName||"").trim();
    const full = common || `${fn} ${ln}`.trim() || (e.player||"").trim() || "Jugador";
    let short;
    if(common) short=common;
    else if(fn && ln) short=`${fn.charAt(0)}. ${ln}`;
    else short = ln || fn || full;
    return { short: short||full, full };
  }
  // Sin jugador enlazado: derivar de la cadena del archivo.
  const raw=((e&&e.player)||"").trim();
  const parts=raw.split(/\s+/);
  const short = (parts.length>=2 && parts[0]) ? `${parts[0].charAt(0)}. ${parts.slice(1).join(" ")}` : raw;
  return { short: short||raw, full: raw };
}
// Árbitro(s) del partido, enlazables. Amistosos usan f.refereeId; los del torneo, su número oficial.
function calRefLinked(f){
  let refs=[];
  if(f && f.refereeId){ const r=(DB.referees||[]).find(x=>x.id===f.refereeId); if(r) refs=[r]; }
  else if(f && f.matchNo && typeof refereesForMatch==="function"){ try{ refs=refereesForMatch(f.matchNo)||[]; }catch(e){} }
  if(!refs.length) return "";
  const canLink=typeof navigateToReferee==="function";
  return refs.map(r=>{
    const nm=(r.commonName||((r.firstName||"")+" "+(r.lastName||""))).trim();
    const code=mrRefCountryCode(r);
    const nameHTML=(canLink&&r.id!=null)?`<span class="jg-lnk2" data-action="open-referee" data-id="${r.id}">${esc(nm)}</span>`:esc(nm);
    return code ? `${nameHTML} (${esc(code)})` : nameHTML;
  }).join(", ");
}
// Código de país (FIFA, o COI de respaldo) del árbitro, para mostrarlo junto al nombre: "Madrigal (CRC)".
function mrRefCountryCode(r){
  if(!r) return "";
  const cid=r.countryRepresentsId || (r.nationalityIds && r.nationalityIds[0]) || null;
  if(!cid) return "";
  const c=(DB.countries||[]).find(x=>x.id===cid);
  if(!c) return "";
  return String(c.fifaCode || c.iocCode || "").toUpperCase();
}
// Logo del torneo para la lista/cuadrícula. dark = usar la versión para fondo oscuro (lista y cuadrícula
// lila la usan). El del Mundial, o el de la FIFA en amistosos. Respaldo de texto si aún no hay imagen.
function calTournLogoHTML(f, cls, dark){
  const isFriendly=!!(f.friendly||f.stage==="amistoso");
  cls=cls||"jg-mtourlogo";
  if(isFriendly){
    const f2=DB.fifa||{}; const lg=dark?(f2.logoImg||f2.logoImgLight):(f2.logoImgLight||f2.logoImg);
    if(typeof lg==="string"&&lg.indexOf("data:")===0) return `<img class="${cls}" src="${lg}" alt="FIFA" title="Amistoso">`;
    return `<span class="jg-mtourtxt" title="Amistoso">FIFA</span>`;
  }
  // Torneo propio (no Mundial): su logo o su código/nombre corto, NUNCA el del Mundial.
  if(f.competition && typeof matchIsWorldCup==="function" && !matchIsWorldCup(f)){
    const c=(typeof competitionByName==="function")?competitionByName(f.competition):null;
    const lg2=c && (dark?(c.logoImg||c.logoImgLight):(c.logoImgLight||c.logoImg));
    if(typeof lg2==="string"&&lg2.indexOf("data:")===0) return `<img class="${cls}" src="${lg2}" alt="" title="${esc(tournamentName(f))}">`;
    const code2=(c&&(c.code||c.shortName)) || String(f.competition||"").slice(0,6);
    return `<span class="jg-mtourtxt" title="${esc(tournamentName(f))}">${esc(code2)}</span>`;
  }
  const ev=DB.event||{}; const lg=dark?(ev.logoImg||ev.logoImgLight):(ev.logoImgLight||ev.logoImg);
  if(typeof lg==="string"&&lg.indexOf("data:")===0) return `<img class="${cls}" src="${lg}" alt="" title="${esc(tournamentName(f))}">`;
  let code="FWC26"; try{ if(typeof eventFieldText==="function"){ const c=eventFieldText(ev,'code'); if(c) code=c; } }catch(e){}
  return `<span class="jg-mtourtxt" title="${esc(tournamentName(f))}">${esc(code)}</span>`;
}
// Enlace del torneo (lleva al perfil del evento); "Amistoso" no tiene perfil.
function calTourLinkHTML(f, cls, dark){
  const isFriendly=!!(f.friendly||f.stage==="amistoso");
  const inner=calTournLogoHTML(f, cls, dark);
  const isComp = f.competition && typeof matchIsWorldCup==="function" && !matchIsWorldCup(f);
  if(isFriendly || isComp) return inner;
  const evLink=(typeof navigateTo==="function")?`onclick="navigateTo('evento')"`:"";
  return `<span class="jg-lnk2" ${evLink}>${inner}</span>`;
}
// Nombre corto del torneo para la etiqueta (logo + nombre) de la lista/cuadrícula.
function calTourName(f){
  if(f.friendly||f.stage==="amistoso") return "Amistoso";
  if(f.competition && typeof matchIsWorldCup==="function" && !matchIsWorldCup(f)){
    const c=(typeof competitionByName==="function")?competitionByName(f.competition):null;
    return (c&&(c.shortName||c.commonName)) || ((typeof competitionDisplayName==="function")?competitionDisplayName(f.competition):f.competition);
  }
  try{ if(typeof eventFieldText==="function"){ const s=eventFieldText(DB.event,'shortName'); if(s) return s; } }catch(e){}
  return "Copa Mundial";
}
// Solo la IMAGEN del logo del torneo (o de la FIFA en amistosos), o "" si aún no hay imagen.
function calTourLogoImgOnly(f, cls, dark){
  const isFriendly=!!(f.friendly||f.stage==="amistoso");
  // Torneo propio (no Mundial): su logo, si tiene.
  if(!isFriendly && f.competition && typeof matchIsWorldCup==="function" && !matchIsWorldCup(f)){
    const c=(typeof competitionByName==="function")?competitionByName(f.competition):null;
    const lg2=c && (dark?(c.logoImg||c.logoImgLight):(c.logoImgLight||c.logoImg));
    return (typeof lg2==="string"&&lg2.indexOf("data:")===0)?`<img class="${cls||'logo-ic'}" src="${lg2}" alt="">`:"";
  }
  let lg;
  if(isFriendly){ const f2=DB.fifa||{}; lg=dark?(f2.logoImg||f2.logoImgLight):(f2.logoImgLight||f2.logoImg); }
  else { const ev=DB.event||{}; lg=dark?(ev.logoImg||ev.logoImgLight):(ev.logoImgLight||ev.logoImg); }
  return (typeof lg==="string"&&lg.indexOf("data:")===0)?`<img class="${cls||'logo-ic'}" src="${lg}" alt="">`:"";
}
// Etiqueta torneo estilo "logo + nombre de club": logo a la izquierda, nombre a la derecha, juntos.
// Si el torneo tiene wordmark, se usa solo la wordmark. Enlaza al evento (los amistosos no).
function calTourChipHTML(f, dark){
  const isFriendly=!!(f.friendly||f.stage==="amistoso");
  // Siempre logo + nombre corto (sin wordmark): (logo) Copa Mundial 2026 / (logo) Amistoso.
  const inner=`${calTourLogoImgOnly(f,"logo-ic",dark)}<span class="jg-tourchip-nm">${esc(calTourName(f))}</span>`;
  const isComp = f.competition && typeof matchIsWorldCup==="function" && !matchIsWorldCup(f);
  // Amistoso y torneos propios (no Mundial): SIN enlace al evento.
  if(isFriendly || isComp) return `<span class="jg-tourchip">${inner}</span>`;
  const evLink=(typeof navigateTo==="function")?`onclick="navigateTo('evento')"`:"";
  return `<span class="jg-tourchip jg-lnk2" ${evLink}>${inner}</span>`;
}
// Enlace de equipo (navega al perfil).
function calTeamLink(x){ return x?`<span class="jg-lnk2" data-action="open-team" data-id="${x.id}">${esc(teamName(x))}</span>`:"—"; }
// Escudo mini de un equipo (para la cuadrícula), enlazable. dark = logo para fondo oscuro.
function calMiniCrest(x, dark){
  if(!x) return "";
  const src=dark?(x.logoImg||x.logoImgLight):(x.logoImgLight||x.logoImg);
  const inner=(typeof src==="string"&&src.indexOf("data:")===0)?`<img src="${src}" alt="">`
    :((typeof DEFAULT_CREST_SRC==="string"&&DEFAULT_CREST_SRC)?`<img src="${DEFAULT_CREST_SRC}" alt="" onerror="this.style.display='none'">`:`<span class="ge-code">${esc(teamCode(x))}</span>`);
  return `<span class="ge-crest jg-lnk2" data-action="open-team" data-id="${x.id}">${inner}</span>`;
}
// Icono de una incidencia: balón (gol, blanco), o tarjeta amarilla/roja (rectángulo).
function calIncidentIcon(kind, og, title){
  if(kind==="red") return `<span class="inc-card red" title="Tarjeta roja"></span>`;
  if(kind==="yellow") return `<span class="inc-card yellow" title="Tarjeta amarilla"></span>`;
  // Gol en contra: balón ROJO (mismo dibujo, teñido con el PNG como máscara).
  if(og) return `<span class="inc-ball og-ball" title="Gol en contra" style="display:inline-block;background:var(--coral,#E1473A);-webkit-mask:url('${JG_BALL_ICON}') center/contain no-repeat;mask:url('${JG_BALL_ICON}') center/contain no-repeat;"></span>`;
  return `<img class="inc-ball" src="${JG_BALL_ICON}" alt="gol" title="${esc(title||'Gol')}">`;
}
// Incidencias del partido DEBAJO del cuadro: dos columnas (local | visitante) separadas por una línea.
// Iconos al centro (junto a la línea), datos del jugador hacia los extremos.
function calIncidentsHTML(f, t){
  const evAll=[];
  (f.goals||[]).forEach(g=>evAll.push({playerId:g.playerId, player:g.player, teamId:g.teamId, minute:g.minute, kind:"goal", og:!!g.og, penalty:!!g.penalty, assistPlayerId:g.assistPlayerId||null, assistPlayer:g.assistPlayer||null, min:parseInt(g.minute)||0}));
  // Solo goles y ROJAS aquí (las amarillas van únicamente en la línea de tiempo del informe).
  (f.cards||[]).forEach(c=>{ if((c.type||"yellow")!=="red") return; evAll.push({playerId:c.playerId, player:c.player, teamId:c.teamId, minute:c.minute, kind:"red", min:parseInt(c.minute)||0}); });
  const left=evAll.filter(e=>e.teamId===f.teamA).sort((a,b)=>a.min-b.min);
  const right=evAll.filter(e=>e.teamId===f.teamB).sort((a,b)=>a.min-b.min);
  const row=(e,side)=>{
    const info=calIncidentName(e);   // {short: "J. David" / nombre común, full: nombre completo}
    const nmH=e.playerId
      ? `<span class="jg-lnk2" data-action="open-player" data-id="${e.playerId}" title="${esc(info.full)}">${esc(info.short)}</span>`
      : `<span title="${esc(info.full)}">${esc(info.short)}</span>`;
    const tag=e.og?` <span class="inc-tag" title="Gol en contra">(GEC)</span>`:(e.penalty?` <span class="inc-tag" title="Penalti">(PEN)</span>`:"");
    const txt=`<span class="inc-txt">${nmH} ${esc(e.minute)}'${tag}</span>`;
    // El balón muestra el detalle al pasar el cursor: "Gol" / "Gol de penal", y la asistencia si la hubo.
    let goalTitle = e.penalty ? "Gol de penal" : "Gol";
    if(e.kind==="goal" && !e.og && e.assistPlayer) goalTitle += " - Asistencia de " + e.assistPlayer;
    const ico=calIncidentIcon(e.kind, e.og, goalTitle);
    return side==="left"?`<div class="inc-row left">${txt}${ico}</div>`:`<div class="inc-row right">${ico}${txt}</div>`;
  };
  return `<div class="jg-incidents">
    <div class="inc-col left">${left.map(e=>row(e,"left")).join("")}</div>
    <div class="inc-div"></div>
    <div class="inc-col right">${right.map(e=>row(e,"right")).join("")}</div>
  </div>`;
}
// Fila de un partido en la lista: Partido (con guion) arriba; hora · estadio · ciudad · país abajo.
// El árbitro, el grupo y los goles NO van aquí (están en el cuadro de la derecha). Torneo a la derecha.
function calMatchRowHTML(f, t){
  const o=oppOf(f); const home=(f.teamA===t.id); const A=home?t:o, B=home?o:t;
  const dd=f.date?f.date.slice(8,10):"–"; const mo=f.date?monShort(f.date):"";
  const mid=fxPlayed(f)?`<span class="jg-mscore">${f.scoreA} - ${f.scoreB}</span>`:`<span class="jg-mvs">-</span>`;
  const vp=venueParts(f);
  const meta=[ f.time||"", vp&&vp.name?esc(vp.name):"", vp&&vp.loc?esc(vp.loc):"" ].filter(Boolean).join(" · ");
  const selCls=(f.id===calSelId)?" sel":"";
  const badge=fxPlayed(f)?`<span class="badge ok jg-mbadge">Jugado</span>`:`<span class="badge jg-mbadge jg-badge-pend">Por jugarse</span>`;
  return `<div class="jg-match cal${selCls}" data-calsel="${esc(f.id)}"><div class="dt"><div class="dd">${dd}</div><div class="mo">${mo}</div></div>
    <div style="flex:1;min-width:0;"><div class="tm">${calTeamLink(A)} ${mid} ${calTeamLink(B)}</div><div class="me">${meta}</div></div>
    <div class="jg-mright">${calTourChipHTML(f,true)}${badge}</div></div>`;
}
// Cuadro de detalle a la derecha (estética de "Próximo partido", sin título). Las incidencias van
// DEBAJO, separadas. Si el partido no se ha jugado, el cuadro tiene esquinas redondas; si ya se jugó,
// borde inferior recto para unirse a las incidencias.
function calDetailCardHTML(f, t, opts){
  if(!f) return `<div class="jg-matchdetail"><div class="jg-nextmatch"><div class="jg-nm-main" style="margin:auto 0;"><div class="jg-nm-center"><div class="teams" style="color:#3a3b52;">Selecciona un partido de la lista</div></div></div></div></div>`;
  const isFriendly=!!(f.friendly||f.stage==="amistoso");
  // El rival se toma del PROPIO partido respecto a t (no de oppOf, que usa la selección del usuario y
  // duplicaría el nombre cuando se ve un partido ajeno, p. ej. desde el informe).
  const home=(f.teamA===t.id); const o=getTeam(f.teamA===t.id?f.teamB:f.teamA); const A=home?t:o, B=home?o:t;
  const aName=A?`<span class="jg-lnk2" data-action="open-team" data-id="${A.id}">${esc(teamName(A))}</span>`:"—";
  const bName=B?`<span class="jg-lnk2" data-action="open-team" data-id="${B.id}">${esc(teamName(B))}</span>`:"—";
  const played=fxPlayed(f);
  // El partido jugado abre el INFORME al hacer clic (en el marcador o en el rectángulo). opts.clickable
  // desactiva el enlace cuando el propio informe reutiliza esta tarjeta (evita reabrirse a sí mismo).
  const canReport = played && (!opts || opts.clickable!==false);
  const scoreAct = canReport ? `data-action="open-match-report" data-fx="${esc(f.id)}" style="cursor:pointer;"` : "";
  const teamsLine=played?`${aName} <span class="jg-nm-sc" ${scoreAct}>${f.scoreA} - ${f.scoreB}</span> ${bName}`:`${aName} - ${bName}`;
  const l2=[]; const sg=stageOrGroup(f); if(sg) l2.push(sg); if(f.date) l2.push(fmtDateLong(f.date)); if(f.time) l2.push(f.time);
  const vp=venueParts(f); const ref=calRefLinked(f);
  const att=played ? (f.closedDoors ? "Jugado a puerta cerrada" : (f.attendance!=null?`Asistencia: ${Number(f.attendance).toLocaleString("es-MX")}`:"")) : "";
  // El rectángulo inferior (incidencias) solo si el partido YA se jugó (según el reloj). Sin jugar, no va.
  // opts.noIncidents: el informe lo dibuja aparte (columna central), así que aquí se omite.
  const incidents=(played && !(opts&&opts.noIncidents))?calIncidentsHTML(f,t):"";
  const cardAct = canReport ? `data-action="open-match-report" data-fx="${esc(f.id)}" style="${matchBackStyle(f)}cursor:pointer;"` : `style="${matchBackStyle(f)}"`;
  const card=`<div class="jg-nextmatch${matchCardBgCls(f)}${incidents?' played':''}" ${cardAct}>
    <div class="jg-nm-main">
      <div class="jg-nm-badge${A?' jg-lnk2':''}" ${A?`data-action="open-team" data-id="${A.id}"`:""}>${A?nmBadgeInner(A,matchLogoDark(f)):""}</div>
      <div class="jg-nm-center">
        <div class="teams">${teamsLine}</div>
        <div class="tour">${matchTourHTML(f)}</div>
        <div class="meta">${l2.join(" · ")}</div>
        ${vp?`<div class="venue">${vp.name?`<span>${esc(vp.name)}${vp.loc?",":""}</span>`:""}${vp.loc?`<span>${esc(vp.loc)}</span>`:""}</div>`:""}
        ${att?`<div class="ref">${att}</div>`:""}
        ${ref?`<div class="ref">Árbitro: ${ref}</div>`:""}
      </div>
      <div class="jg-nm-badge${B?' jg-lnk2':''}" ${B?`data-action="open-team" data-id="${B.id}"`:""}>${B?nmBadgeInner(B,matchLogoDark(f)):""}</div>
    </div>
  </div>`;
  return `<div class="jg-matchdetail">${card}${incidents}</div>`;
}

/* ============================================================
   INFORME DE PARTIDO (ventana completa): tarjeta de detalle + incidencias +
   canchas (local/visitante) + línea de tiempo + estadísticas.
   ============================================================ */
// Nombre corto "Richard Ledezma" -> "R. Ledezma".
function mrShort(name){
  const parts=String(name||"").trim().split(/\s+/); if(!parts.length) return "";
  if(parts.length===1) return parts[0];
  return parts[0].charAt(0).toUpperCase()+". "+parts.slice(1).join(" ");
}
function mrTeamCode(t){ return t ? (t.fifaCode || t.code || (t.commonName||t.name||"").slice(0,3).toUpperCase()) : ""; }
// Posición en % de un minuto sobre la línea (0–45 → 4–48; 45–90 → 52–96; descuento hacia el final).
// Posición en % de un minuto sobre la línea. El descuento (90+n) se REPARTE hacia el extremo derecho
// para que no se amontonen (90+2, 90+8… caen en puntos distintos); igual el descuento del primer tiempo.
// Minuto "lineal" para posicionar: base + añadido (90+12 → 102). Sirve para escalar el segundo tiempo.
function mrLinMin(minStr){
  const s=String(minStr); const b=parseInt(s)||0; const em=/\+(\d+)/.exec(s); return b + (em?parseInt(em[1],10):0);
}
// Posición X (%) de un minuto en la línea de tiempo. Todo cae SIEMPRE DENTRO de la línea (nada pasa de F).
//   I(inicio)=3% · MT(medio tiempo)=50% · F(final)=97% (extremo útil de la línea).
//   · 1'..44'  → primer tiempo, entre I y el MT.
//   · 45'      → EXACTAMENTE en el medio tiempo (subs/tarjetas al descanso).
//   · 45+X'    → añadido del primer tiempo: JUSTO antes del MT (sucede antes del descanso).
//   · 46'..90' → segundo tiempo: del MT hasta N90 (el minuto 90 va PEGADO al final).
//   · 90+X'    → añadido del segundo tiempo: franja angosta y pegada al final, de N90 hasta F.
//   El tiempo regular (0–90) ocupa casi toda la línea; el añadido queda comprimido junto a F. ftL es el
//   minuto lineal del final (FT): solo define cómo se reparte el añadido dentro de esa franja del final.
function mrEventX(minStr, ftL){
  const s=String(minStr); const b=parseInt(s)||0; const em=/\+(\d+)/.exec(s); const extra=em?parseInt(em[1],10):0;
  const I=3, MT=50, F=97;
  const ftExtra = Math.max(((ftL && ftL>90) ? ftL : 95) - 90, 0);   // minutos de añadido del 2T (FT − 90)
  const band = ftExtra>0 ? 3 : 0;   // franja del añadido, angosta y pegada al final; sin añadido, el 90' va en F
  const N90 = F - band;             // el minuto 90 queda pegado al final
  let x;
  if(b<45){ x = I + b/45*(MT-I); }
  else if(b===45){ x = extra>0 ? (MT - 1.6 + Math.min(extra,6)/6*1.3) : MT; }    // 45+X antes del MT; 45' en el MT
  else if(b<90){ x = MT + (b-45)/45*(N90-MT); }                                  // 46..89 → MT..N90
  else { x = extra>0 ? (N90 + Math.min(extra,ftExtra)/Math.max(ftExtra,1)*band) : N90; }  // 90'→N90; 90+X→N90..F
  return Math.max(3, Math.min(F, x));   // nunca fuera de la línea del tiempo
}
// Minuto lineal del FINAL del partido, para escalar la línea de tiempo:
//   · Si el archivo trae "FT ..." → ese minuto (extendido si algún evento lo pasara).
//   · Si no, y no hay nada después del 90+5 → 90+5 (95).
//   · Si no, pero hay un evento más allá del 90+5 → ese último evento marca el final.
function mrFullTimeLin(f, evs){
  let maxL = 0; (evs||[]).forEach(e=>{ const L=mrLinMin(e.min); if(L>maxL) maxL=L; });
  if(f && f.ftMin){ return Math.max(mrLinMin(f.ftMin), maxL); }
  return Math.max(95, maxL);
}
// Icono de sustitución: MISMO estilo que el balón (disco claro) con dos flechas gruesas (entra/sale).
const MR_SUB_ICON = `<svg class="mr-subsvg" viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="M8.5 20 L8.5 5 M8.5 5 L4.7 9.4 M8.5 5 L12.3 9.4" stroke="#2fae66" stroke-width="3.1" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M15.5 4 L15.5 19 M15.5 19 L11.7 14.6 M15.5 19 L19.3 14.6" stroke="#e0574f" stroke-width="3.1" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
function mrEventIcon(e){
  if(e.kind==="goal"){ const col = e.og ? "var(--coral,#E1473A)" : "#e9edf5"; return `<span class="mr-ball" style="background:${col};-webkit-mask:url('${JG_BALL_ICON}') center/contain no-repeat;mask:url('${JG_BALL_ICON}') center/contain no-repeat;"></span>`; }
  if(e.kind==="yellow") return `<span class="mr-cardic yellow"></span>`;
  if(e.kind==="red") return `<span class="mr-cardic red"></span>`;
  if(e.kind==="sub") return MR_SUB_ICON;
  return "";
}
function mrEventTip(e, code){
  const m=`${esc(e.min)}'`;
  if(e.kind==="goal") return e.og
    ? `${m} ${code}: ${esc(mrShort(e.who))} — Gol en contra`
    : `${m} ${code}: ${esc(mrShort(e.who))} — Gol${e.pen?" (penal)":""}${e.assist?` · Asistencia de ${esc(mrShort(e.assist))}`:""}`;
  if(e.kind==="yellow") return `${m} ${code}: ${esc(mrShort(e.who))} — Amarilla`;
  if(e.kind==="red") return `${m} ${code}: ${esc(mrShort(e.who))} — Roja`;
  if(e.kind==="sub") return `${m} ${code}: entra ${esc(mrShort(e.inName))}, sale ${esc(mrShort(e.outName))}`;
  return m;
}
// Reúne todos los sucesos del partido para la línea de tiempo (goles, amarillas, rojas, cambios).
function mrTimelineEvents(f){
  const evs=[];
  (f.goals||[]).forEach(g=>evs.push({teamId:g.teamId, min:g.minute, kind:"goal", og:!!g.og, pen:!!g.penalty, who:g.player, assist:g.assistPlayer||null}));
  (f.cards||[]).forEach(c=>{ const k=(c.type||"yellow"); if(k!=="yellow"&&k!=="red") return; evs.push({teamId:c.teamId, min:c.minute, kind:k, who:c.player}); });
  ["home","away"].forEach(side=>{ const lu=f.lineups&&f.lineups[side]; if(!lu) return; (lu.players||[]).forEach(pl=>{ if(pl.sub&&pl.sub.minute){ evs.push({teamId:lu.teamId, min:pl.sub.minute, kind:"sub", inName:pl.sub.name, outName:pl.name}); } }); });
  return evs;
}
// Categoría (GK/DF/MF/FW) de una posición del archivo.
function mrCatOf(pos){
  if(typeof POS_CAT_OF==="object" && POS_CAT_OF[pos]) return POS_CAT_OF[pos];
  if(pos==="GK") return "GK";
  if(["LB","RB","CB","LWB","RWB","DF"].indexOf(pos)>=0) return "DF";
  if(["LW","RW","ST","CF","FW"].indexOf(pos)>=0) return "FW";
  return "MF";
}
// Formación del archivo (número + tipo) → clave del catálogo de formaciones (con el tipo H/A/D/N/W).
function mrFormationKey(formation, type){
  const P=window.CM_PITCH; if(!P||!P.FORMATIONS) return null; const F=P.FORMATIONS;
  const tw={H:"Holding",A:"Attack",D:"Defend",N:"Narrow",W:"Wide"}[String(type||"").toUpperCase()];
  if(tw && F[formation+" ("+tw+")"]) return formation+" ("+tw+")";
  if(F[formation]) return formation;
  return Object.keys(F).find(k=>k===formation || k.indexOf(formation+" ")===0) || null;
}
// Lado horizontal de una posición: izquierda(0) / centro(1) / derecha(2). Sirve para RESPETAR el sitio
// que la formación ya define (ST va al centro, LB a la izquierda, etc.), no colocarlos literalmente 1→11.
function mrSideRank(pos){
  const p=String(pos||"").toUpperCase();
  if(/^(L)(B|WB|M|W|F)$/.test(p) || p==="LCB") return 0;
  if(/^(R)(B|WB|M|W|F)$/.test(p) || p==="RCB") return 2;
  return 1;
}
// Posición canónica: unifica los sinónimos del archivo con las etiquetas del catálogo de formaciones,
// para poder emparejar EXACTAMENTE (p. ej. DM→CDM, AM→CAM, CF→ST, LCB→CB). Se aplica a jugadores Y slots.
function mrPosCanon(pos){
  const p=String(pos||"").toUpperCase().trim();
  const map={
    GK:"GK", SW:"CB",
    LB:"LB", RB:"RB", LWB:"LWB", RWB:"RWB",
    CB:"CB", LCB:"CB", RCB:"CB",
    DM:"CDM", CDM:"CDM", LDM:"CDM", RDM:"CDM",
    CM:"CM", LCM:"CM", RCM:"CM", LM:"LM", RM:"RM",
    AM:"CAM", CAM:"CAM", LAM:"CAM", RAM:"CAM",
    LW:"LW", RW:"RW", LF:"LW", RF:"RW",
    ST:"ST", CF:"ST", SS:"ST", ST1:"ST", ST2:"ST"
  };
  return map[p] || p;
}
// Asigna los jugadores a los slots de la formación. Cada slot ya trae su posición EXACTA (CM, CDM, CAM,
// CB, LB…). Regla (para TODAS las posiciones):
//   1) Se empareja por posición EXACTA. Si hay varios de la misma posición, se toman en el orden de la
//      lista (izq→der en el archivo) y se colocan en sus slots ordenados de izquierda a derecha
//      (p. ej. CM, CDM, CM → primer CM a la izquierda, CDM al centro, segundo CM a la derecha).
//   2) Lo que no cuadre por posición exacta cae al reparto por categoría + lado (izq/centro/der).
function mrAssignToSlots(slots, players){
  const out=new Array(slots.length).fill(null);
  const slotUsed=new Array(slots.length).fill(false);
  const playerUsed=new Array(players.length).fill(false);

  // 1) Coincidencia EXACTA por posición canónica.
  const slotByPos={}; slots.forEach((s,i)=>{ const p=mrPosCanon(s.p); (slotByPos[p]=slotByPos[p]||[]).push(i); });
  Object.keys(slotByPos).forEach(p=> slotByPos[p].sort((a,b)=> slots[a].c - slots[b].c));   // slots izq→der
  const playersByPos={}; players.forEach((pl,idx)=>{ const p=mrPosCanon(pl.pos); (playersByPos[p]=playersByPos[p]||[]).push(idx); });
  Object.keys(playersByPos).forEach(p=>{
    const sidxs=slotByPos[p]; if(!sidxs) return;
    const pidxs=playersByPos[p];   // ya en el orden de la lista (izq→der del archivo)
    const n=Math.min(sidxs.length, pidxs.length);
    for(let k=0;k<n;k++){ out[sidxs[k]]=players[pidxs[k]]; slotUsed[sidxs[k]]=true; playerUsed[pidxs[k]]=true; }
  });

  // 2) Resto: por categoría (GK/DF/MF/FW) + lado (izq/centro/der), como respaldo.
  const restSlots=[]; slots.forEach((s,i)=>{ if(!slotUsed[i]) restSlots.push(i); });
  const scat={}; restSlots.forEach(i=>{ const c=slots[i].cat||mrCatOf(slots[i].p); (scat[c]=scat[c]||[]).push(i); });
  const pcat={}; players.forEach((pl,idx)=>{ if(playerUsed[idx]) return; const c=mrCatOf(pl.pos); (pcat[c]=pcat[c]||[]).push(idx); });
  Object.keys(scat).forEach(cat=>{
    const sl=scat[cat].sort((a,b)=> slots[a].c - slots[b].c);                 // slots izq→der
    const pl=(pcat[cat]||[]).slice().sort((a,b)=> mrSideRank(players[a].pos)-mrSideRank(players[b].pos) || a-b);
    sl.forEach((si,k)=>{ const idx=pl[k]; if(idx!=null){ out[si]=players[idx]; slotUsed[si]=true; playerUsed[idx]=true; } });
  });

  // 3) Sobrantes sin categoría que cuadre: rellena los slots vacíos en orden de lista.
  let ri=0; const stillPlayers=[]; players.forEach((pl,idx)=>{ if(!playerUsed[idx]) stillPlayers.push(idx); });
  for(let i=0;i<out.length && ri<stillPlayers.length;i++){ if(!out[i]) out[i]=players[stillPlayers[ri++]]; }
  return out;
}
// Cancha con la alineación, IGUAL que el onboarding: foto + nombre + chip de posición.
function mrPitchHTML(entry){
  const P=window.CM_PITCH; const img=(P&&P.img)?P.img:"";
  if(!entry || !P || !P.FORMATIONS) return `<div class="jgt-pitch"><div class="jgt-field" style="background-image:url('${img}')"></div></div>`;
  const tm=getTeam(entry.teamId); const byId={}; ((tm&&tm.players)||[]).forEach(p=>byId[p.id]=p);
  const slotHTML=(lp, x, y, fallbackPos, fallbackCat)=>{
    if(!lp) return `<div class="jgt-slot" style="left:${x}%;top:${y}%;"><div class="jgt-face empty"></div><span class="pos-chip pos-${VALID4.has(fallbackCat)?fallbackCat:'MF'} jgt-pos">${esc(fallbackPos||"")}</span></div>`;
    const obj = lp.playerId ? byId[lp.playerId] : null;
    const cat = mrCatOf(lp.pos);
    const face = obj ? `<div class="jgt-face">${personPhotoHTML(obj,"width:100%;height:100%;")}</div>` : `<div class="jgt-face empty"></div>`;
    // En la cancha se muestra SOLO el apellido o el nombre común.
    const surname = obj ? (obj.commonName || obj.lastName || pname(obj)) : (String(lp.name||"").trim().split(/\s+/).slice(-1)[0] || lp.name || "");
    const nameHTML = `<b>${esc(surname)}</b>`;
    const numHTML = (lp.number!=null) ? `<span class="mr-num">${esc(String(lp.number))}</span>` : "";
    const name = `<div class="jgt-name mr-pname" title="${esc(obj?pname(obj):(lp.name||''))}">${numHTML}${nameHTML}</div>`;
    const clk = obj ? ` data-action="open-player" data-id="${esc(obj.id)}" style="left:${x}%;top:${y}%;cursor:pointer;"` : ` style="left:${x}%;top:${y}%;"`;
    // Capitán: icono C sobre la esquina de la foto (como en Plantilla).
    const capBadge = lp.captain ? `<span class="jgt-cap" title="Capitán"><img src="${JG_CAP_ICON}" alt="C"></span>` : "";
    const faceBox = `<div class="jgt-facewrap">${face}${capBadge}</div>`;
    return `<div class="jgt-slot"${clk}>${faceBox}${name}<span class="pos-chip pos-${VALID4.has(cat)?cat:'MF'} jgt-pos">${esc(lp.pos||"")}</span></div>`;
  };
  const key=mrFormationKey(entry.formation, entry.formationType);
  if(key && P.FORMATIONS[key]){
    const f=P.FORMATIONS[key];
    const assigned=mrAssignToSlots(f.slots, (entry.players||[]).slice());
    const cols=f.slots.map(s=>s.c); const mid=(Math.min.apply(null,cols)+Math.max.apply(null,cols))/2; const shift=(P.GRID_COLS+1)/2-mid;
    const slots=f.slots.map((s,si)=>{ const x=P.cellX(s.c+shift), y=P.cellY(s.r); return slotHTML(assigned[si], x, y, s.p, s.cat); }).join("");
    return `<div class="jgt-pitch"><div class="jgt-field" style="background-image:url('${P.img}')"></div><div class="jgt-layer">${slots}</div></div>`;
  }
  // Fallback: coloca por líneas de la formación si no está en el catálogo (mismo estilo de slot).
  const players=(entry.players||[]).slice(); let gk=null; const outp=[];
  players.forEach(p=>{ if(!gk && p.pos==="GK") gk=p; else outp.push(p); }); if(!gk) gk=outp.shift()||null;
  const nums=String(entry.formation||"").split("-").map(n=>parseInt(n,10)).filter(n=>n>0);
  const lines=[]; let idx=0; nums.forEach(n=>{ lines.push(outp.slice(idx, idx+n)); idx+=n; }); if(idx<outp.length) lines.push(outp.slice(idx));
  const yBot=78, yTop=17; const nL=lines.length; let html="";
  if(gk) html+=slotHTML(gk,50,90);
  lines.forEach((line,i)=>{ const y=nL>1?(yBot-i*(yBot-yTop)/(nL-1)):(yBot+yTop)/2; const n=line.length; line.forEach((p,j)=>{ const x=(n===1)?50:(16+j*68/(n-1)); html+=slotHTML(p,x,y); }); });
  return `<div class="jgt-pitch"><div class="jgt-field" style="background-image:url('${img}')"></div><div class="jgt-layer">${html}</div></div>`;
}
// Línea de tiempo: local arriba, visitante abajo; IN — MT — F.
function mrTimelineHTML(f, A, B){
  const evs=mrTimelineEvents(f);
  const codeA=mrTeamCode(A), codeB=mrTeamCode(B);
  const ftL=mrFullTimeLin(f, evs);   // largo de la línea (minuto lineal del final)
  const minKey=(m)=>String(m).replace(/[^0-9+]/g,"");
  // Tooltip por MINUTO: lista TODOS los sucesos de ese minuto (local primero, luego visitante) en varias
  // líneas — como en la referencia (dos amarillas al 54’ muestran ambas).
  const minTip={};
  [...evs].sort((a,b)=>((a.teamId===f.teamA?0:1)-(b.teamId===f.teamA?0:1))).forEach(e=>{
    const k=minKey(e.min); const code=e.teamId===f.teamA?codeA:codeB;
    (minTip[k]=minTip[k]||[]).push(mrEventTip(e, code));
  });
  // Mapa ÚNICO minuto→posición: los iconos y la guía punteada de un minuto usan la MISMA X (así la línea
  // SIEMPRE cae sobre el icono). Si dos minutos quedan muy pegados, se separan el ancho de un icono.
  const ICON_GAP=2.2;
  const mins=[...new Set(evs.map(e=>minKey(e.min)))].map(k=>({k, x:mrEventX(k, ftL)})).sort((a,b)=>a.x-b.x);
  for(let i=1;i<mins.length;i++){ if(mins[i].x - mins[i-1].x < ICON_GAP) mins[i].x = mins[i-1].x + ICON_GAP; }
  // El 45' (exacto) SIEMPRE cae en el MT, aunque haya sucesos pegados (ancla del descanso).
  mins.forEach(o=>{ if(o.k==="45") o.x=mrEventX("45", ftL); });
  const minX={}; mins.forEach(o=>{ minX[o.k]=Math.min(o.x, 97); });   // tope en F: nada se sale de la línea
  // Prioridad de apilado dentro de un mismo minuto: goles/autogoles arriba, tarjetas en medio, cambios abajo.
  const EV_PRIO={goal:0, og:0, yellow:1, red:1, sub:2};
  const mk=(list, band)=>{
    // Un icono por TIPO y MINUTO: dos cambios al mismo minuto → un solo icono de cambio. Cuando hay sucesos
    // de DISTINTO tipo en el mismo minuto, se apilan uno sobre otro (gol arriba, luego tarjeta, luego cambio).
    const groups=[]; const byKey={};
    list.forEach(e=>{ const key=e.kind+"@"+minKey(e.min); if(!byKey[key]){ byKey[key]={kind:e.kind, min:e.min, teamId:e.teamId, items:[]}; groups.push(byKey[key]); } byKey[key].items.push(e); });
    const byMin={}; groups.forEach(g=>{ const k=minKey(g.min); (byMin[k]=byMin[k]||[]).push(g); });
    const STEP=13, BASE=9;   // separación vertical entre iconos apilados
    const out=[];
    Object.keys(byMin).forEach(k=>{
      const gs=byMin[k].sort((a,b)=>((EV_PRIO[a.kind]!=null?EV_PRIO[a.kind]:9)-(EV_PRIO[b.kind]!=null?EV_PRIO[b.kind]:9)));
      const n=gs.length, tip=(minTip[k]||[]).join("\n");
      gs.forEach((g,pos)=>{
        // Arriba (local): el gol va MÁS lejos de la línea; abajo (visitante): el gol va PEGADO a la línea.
        const off = BASE + (band==="top" ? (n-1-pos) : pos)*STEP;
        const edge = band==="top" ? `bottom:${off}px;` : `top:${off}px;`;
        out.push(`<div class="mr-ev" data-min="${esc(k)}" style="left:${minX[k]}%;${edge}" data-tip="${esc(tip)}">${mrEventIcon(g.items[0])}</div>`);
      });
    });
    return out.join("");
  };
  const home=evs.filter(e=>e.teamId===f.teamA);
  const away=evs.filter(e=>e.teamId===f.teamB);
  // COLUMNA por minuto: zona sensible de ALTO COMPLETO en la X del evento. Al pasar el cursor por ella
  // —arriba o abajo de la línea— se muestra la guía punteada y el tooltip, sin importar el lado.
  const cols=mins.map(o=>{ const k=o.k; const tip=(minTip[k]||[]).join("\n"); return `<div class="mr-col" style="left:${minX[k]}%;" data-tip="${esc(tip)}"><div class="mr-guide"><span class="mr-guide-min">${esc(String(k))}'</span></div></div>`; }).join("");
  return `<div class="mr-section">
    <div class="mr-h">Línea de tiempo de juego</div>
    <div class="mr-tl">
      <div class="mr-tl-team">${flagImg(A,18)}<span>${esc(codeA)}</span></div>
      <div class="mr-tl-track">
        <div class="mr-tl-half"></div>
        <div class="mr-tl-line"></div>
        <div class="mr-tl-top">${mk(home,"top")}</div>
        <div class="mr-tl-bot">${mk(away,"bot")}</div>
        ${cols}
        <div class="mr-tl-axis"><span class="mr-ax l" title="Inicio">I</span><span class="mr-ax m" title="Medio tiempo">MT</span><span class="mr-ax r" title="Final: ${esc(ftL>90?('90+'+(ftL-90)):String(ftL))}'">F</span></div>
      </div>
      <div class="mr-tl-team">${flagImg(B,18)}<span>${esc(codeB)}</span></div>
    </div>
  </div>`;
}
// Estadísticas de equipo: barra doble (local a la izquierda, visitante a la derecha).
function mrStatsHTML(f, A, B){
  const s=f.stats; if(!s) return "";
  const rows=[["Posesión","pos",true],["Tiros","shots"],["Tiros a puerta","sot"],["Faltas","fouls"],["Tarjetas amarillas","yellows"],["Tarjetas rojas","reds"],["Tiros de esquina","corners"],["Atajadas","saves"]];
  const line=(label,key,pct)=>{
    const v=s[key]; if(!Array.isArray(v)) return "";
    const h=v[0]||0, a=v[1]||0;
    let hp; if(pct){ const tt=h+a; hp = tt? h/tt*100 : 50; } else { const tt=h+a; hp = tt? h/tt*100 : 50; }
    const hv = pct? h+"%" : h, av = pct? a+"%" : a;
    return `<div class="mr-st-row">
      <div class="mr-st-top"><span class="mr-st-v">${esc(String(hv))}</span><span class="mr-st-l">${esc(label)}</span><span class="mr-st-v">${esc(String(av))}</span></div>
      <div class="mr-st-bar"><div class="mr-st-h" style="width:${hp.toFixed(1)}%;"></div><div class="mr-st-a" style="width:${(100-hp).toFixed(1)}%;"></div></div>
    </div>`;
  };
  return `<div class="mr-section">
    <div class="mr-h">Estadísticas de equipo</div>
    <div class="mr-st-head"><div class="mr-st-team">${flagImg(A,18)}<span>${esc(mrTeamCode(A))}</span></div><div class="mr-st-team r"><span>${esc(mrTeamCode(B))}</span>${flagImg(B,18)}</div></div>
    ${rows.map(r=>line(r[0],r[1],r[2])).join("")}
  </div>`;
}
// Flechas de entrada (verde) y salida (roja) para la lista de alineación.
const MR_IN_ARROW=`<svg class="mr-arw" viewBox="0 0 12 12" width="10" height="10" aria-hidden="true"><path d="M6 10 L6 2 M6 2 L3 5 M6 2 L9 5" stroke="#2fae66" stroke-width="1.9" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const MR_OUT_ARROW=`<svg class="mr-arw" viewBox="0 0 12 12" width="10" height="10" aria-hidden="true"><path d="M6 2 L6 10 M6 10 L3 7 M6 10 L9 7" stroke="#e0574f" stroke-width="1.9" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
// Icono de asistencia: zapato de fútbol (imagen aportada por el usuario). Se muestra al MISMO ancho que el balón.
const JG_BOOT_ICON = "data:image/png;base64,";
// Se pinta con máscara para heredar el MISMO color del balón (#e9edf5); el verde del PNG solo define la silueta.
const MR_BOOT_ICON=`<span class="mr-boot" style="background:#e9edf5;-webkit-mask:url('${JG_BOOT_ICON}') center/contain no-repeat;mask:url('${JG_BOOT_ICON}') center/contain no-repeat;"></span>`;
// Agrupa los sucesos REPETIBLES del mismo tipo (goles, autogoles, asistencias, tarjetas) en un solo icono
// con la lista de minutos en orden: (BALÓN) 23', 32', 78'. Entra/sale nunca se agrupan (son únicos).
function mrGroupLuEvents(evs){
  const GROUP=new Set(["goal","og","assist","yellow","red"]);
  const out=[], idx={};
  (evs||[]).forEach(e=>{
    if(GROUP.has(e.kind) && idx[e.kind]!=null){
      const g=out[idx[e.kind]]; g.mins.push(e.min); if(e.pen) g.anyPen=true;
    } else {
      const g={kind:e.kind, mins:[e.min], other:e.other, anyPen:!!e.pen};
      if(GROUP.has(e.kind)) idx[e.kind]=out.length;
      out.push(g);
    }
  });
  return out;
}
// Icono de un suceso de jugador (para la lista): balón/tarjeta reutiliza mrEventIcon; entra/sale son flechas.
// Recibe un suceso ya agrupado (mins: lista de minutos en orden).
function mrLuEvChip(e){
  let ic="", tip="";
  const mins = e.mins || [e.min];
  const pen = (e.anyPen!=null) ? e.anyPen : e.pen;
  if(e.kind==="in"){ ic=MR_IN_ARROW; tip="Entra"+(e.other?" por "+e.other:""); }
  else if(e.kind==="out"){ ic=MR_OUT_ARROW; tip="Sale"+(e.other?" — entra "+e.other:""); }
  else if(e.kind==="goal"){ ic=mrEventIcon({kind:"goal"}); tip=(mins.length>1?"Goles":"Gol")+(pen?" (penal)":""); }
  else if(e.kind==="og"){ ic=mrEventIcon({kind:"goal",og:true}); tip="Gol en contra"; }
  else if(e.kind==="yellow"){ ic=mrEventIcon({kind:"yellow"}); tip="Amarilla"; }
  else if(e.kind==="red"){ ic=mrEventIcon({kind:"red"}); tip="Roja"; }
  else if(e.kind==="assist"){ ic=MR_BOOT_ICON; tip=mins.length>1?"Asistencias":"Asistencia"; }
  const minTxt = mins.map(mn=>esc(String(mn))+"'").join(", ");
  return `<span class="mr-lu-e${e.kind==="assist"?" mr-lu-e-boot":""}" title="${esc(tip)}">${ic}<span class="mr-lu-emin">${minTxt}</span></span>`;
}
// Sucesos de un jugador durante el partido (para la fila de la lista): entra/sale, goles, tarjetas.
function mrPlayerLuEvents(f, playerId, playerName, sub){
  const evs=[];
  if(sub && sub.min){ evs.push({kind:sub.kind, min:sub.min, other:sub.other}); }
  const match=(o)=> (o.playerId && playerId && o.playerId===playerId) || (!o.playerId||!playerId ? (o.player && playerName && o.player===playerName) : false);
  (f.goals||[]).forEach(g=>{ if(match(g)) evs.push({kind:g.og?"og":"goal", min:g.minute, pen:!!g.penalty, m:parseInt(g.minute)||0}); });
  // Asistencias: quien dio el pase de gol lleva un icono de zapato con el minuto del gol.
  (f.goals||[]).forEach(g=>{ if(g.assistPlayerId && playerId && g.assistPlayerId===playerId) evs.push({kind:"assist", min:g.minute, m:parseInt(g.minute)||0}); });
  (f.cards||[]).forEach(c=>{ if(match(c)) evs.push({kind:(c.type||"yellow"), min:c.minute, m:parseInt(c.minute)||0}); });
  evs.forEach(e=>{ if(e.m==null) e.m=parseInt(e.min)||0; });
  return evs.sort((a,b)=>a.m-b.m);
}
// Apellido (última palabra del nombre) para ordenar y para poner en negritas.
function mrSurnameOf(obj, name){
  if(obj && (obj.lastName||"").trim()) return obj.lastName.trim();
  const q=String((obj&&(obj.commonName))||name||"").trim().split(/\s+/);
  return q[q.length-1]||"";
}
// Nombre con el APELLIDO en negritas. Si hay ficha, usa nombre común (o nombre+apellido); si no, el texto dado.
function mrNameBoldHTML(obj, name){
  let full = obj ? (obj.commonName || pname(obj)) : (name||"");
  full = String(full||"").trim();
  if(!full) return "";
  const q=full.split(/\s+/);
  if(q.length<=1) return `<b>${esc(full)}</b>`;
  return `${esc(q.slice(0,-1).join(" "))} <b>${esc(q[q.length-1])}</b>`;
}
// Lista de alineación bajo la cancha: titulares y suplentes. Lado IZQUIERDO: número + nombre + posición y a
// la derecha los sucesos. Lado DERECHO (mirror=true): en ESPEJO — sucesos pegados al centro, luego posición,
// nombre y el número en el extremo; encabezados recargados a la derecha. El apellido va en negritas.
function mrLineupListHTML(entry, f, mirror){
  if(!entry || !(entry.players||[]).length) return "";
  const tm=getTeam(entry.teamId); const byId={}; ((tm&&tm.players)||[]).forEach(p=>byId[p.id]=p);
  const shortNm=(name)=>{ const q=String(name||"").trim().split(/\s+/); return q.length>1?(q[0].charAt(0)+". "+q.slice(1).join(" ")):(q[0]||""); };
  const row=(pid, num, nameHtml, pos, evs, captain, didPlay)=>{
    const cat=mrCatOf(pos);
    const evHTML=mrGroupLuEvents(evs).map(mrLuEvChip).join("");
    // La posición se pega junto al nombre (solo si existe: los suplentes van sin posición).
    const posHTML=pos ? `<span class="pos-chip pos-${VALID4.has(cat)?cat:'MF'} mr-lu-pos">${esc(pos)}</span>` : "";
    // Etiqueta de capitán (icono C) junto a la posición, como en Plantilla.
    const capHTML=captain ? `<span class="mr-lu-cap" title="Capitán"><img src="${JG_CAP_ICON}" alt="C"></span>` : "";
    // Todos los jugadores con ficha son cliqueables (abren su perfil).
    const clk = pid ? ` data-action="open-player" data-id="${esc(pid)}" style="cursor:pointer;"` : "";
    // Recuadro de calificación en el EXTREMO de la fila (mismo tamaño siempre):
    //  · jugó y tiene calificación → número coloreado · jugó <15' → "SC" · NO jugó (banca) → recuadro vacío.
    let rateHTML;
    if(didPlay===false){
      rateHTML = `<span class="mr-lu-rate mr-lu-rate-empty" title="No jugó"></span>`;
    } else {
      const rv=(pid && typeof playerFixtureRating==="function") ? playerFixtureRating(pid, f) : null;
      rateHTML = (rv!=null)
        ? `<span class="mr-lu-rate" style="background:${(typeof pmRendColor==="function")?pmRendColor(rv):"#6fae4e"};" title="Calificación del partido">${rv.toFixed(1)}</span>`
        : `<span class="mr-lu-rate mr-lu-rate-sc" title="Sin calificación (menos de 15 minutos jugados)">SC</span>`;
    }
    return `<div class="mr-lu-row"${clk}>
      <span class="mr-lu-l">
        <span class="mr-lu-num">${num!=null?esc(String(num)):""}</span>
        <span class="mr-lu-nm">${nameHtml}</span>
        ${posHTML}${capHTML}
      </span>
      <span class="mr-lu-ev">${evHTML}</span>
      ${rateHTML}
    </div>`;
  };
  const starters=(entry.players||[]).map(p=>{
    const obj=p.playerId?byId[p.playerId]:null;
    const sub = p.sub&&p.sub.minute ? {kind:"out", min:p.sub.minute, other:shortNm(p.sub.name)} : null;
    return row(p.playerId, p.number, mrNameBoldHTML(obj,p.name), p.pos, mrPlayerLuEvents(f, p.playerId, p.name, sub), p.captain, true);
  }).join("");
  // Suplentes ordenados alfabéticamente por apellido: los que ENTRARON (con sus incidencias) y los que NO
  // jugaron (bloque "Sub CODE", sin incidencias). Solo los porteros muestran su icono de posición.
  const subsPlayed=(entry.players||[]).filter(p=>p.sub).map(p=>{
    const s=p.sub; const obj=s.playerId?byId[s.playerId]:null;
    return { sortKey: mrSurnameOf(obj, s.name).toLocaleLowerCase("es"),
             html: row(s.playerId, s.number, mrNameBoldHTML(obj,s.name), s.pos||"", mrPlayerLuEvents(f, s.playerId, s.name, {kind:"in", min:s.minute, other:shortNm(p.name)}), s.captain, true) };
  });
  const subsBench=(entry.bench||[]).map(bp=>{
    const obj=bp.playerId?byId[bp.playerId]:null;
    return { sortKey: mrSurnameOf(obj, bp.name).toLocaleLowerCase("es"),
             html: row(bp.playerId, bp.number, mrNameBoldHTML(obj,bp.name), bp.pos||"", [], bp.captain, false) };
  });
  const subs=subsPlayed.concat(subsBench).sort((a,b)=>a.sortKey.localeCompare(b.sortKey,"es")).map(x=>x.html);
  return `<div class="mr-lu${mirror?" mr-lu-mirror":""}">
    <div class="mr-lu-h">Titulares</div>${starters}
    <div class="mr-lu-h">Suplentes</div>${subs.length?subs.join(""):`<div class="mr-lu-empty">Sin cambios</div>`}
  </div>`;
}
// Elige un kit de una categoría por número (1-based) dentro del equipo; si no existe, el primero.
function mrPickKit(team, category, num, dateISO){
  // 'num' es el ordinal (Local=1, Visita=2…) dentro de la categoría; la FECHA del partido elige la
  // TEMPORADA vigente y, dentro de ella, ese ordinal. Sin temporadas equivale al comportamiento anterior.
  if(typeof seasonKitByOrdinal==="function"){
    const v=seasonKitByOrdinal(team, category, num, dateISO);
    if(v) return v;
  }
  const list=((team&&team.kits)||[]).filter(k=>k.category===category);
  if(!list.length) return null;
  const i=(num!=null && num>=1 && num<=list.length) ? (num-1) : 0;
  return list[i]||list[0];
}
// Índice de combinación (shorts/calcetas) por número (1-based); si no existe, 0.
function mrComboIndex(kit, num){
  const n=(kit&&kit.combinations)?kit.combinations.length:0;
  if(!n) return 0;
  return (num!=null && num>=1 && num<=n) ? (num-1) : 0;
}
// Uniforme (playera + shorts + calcetas) reutilizando la MISMA previsualización del editor de uniformes.
// Recibe el kit y la combinación ya resueltos (según los uniformes elegidos del partido).
function mrKitBox(team, kit, comboIndex, label){
  if(!team || !kit){
    return `<div class="mr-kit"><div class="mr-kit-prev"><div class="kit-render" style="width:70px;height:70px;background:var(--surface-2);border-radius:8px;"></div></div><div class="mr-kit-lbl">${esc(label)}</div></div>`;
  }
  const ci=comboIndex||0; const tid=esc(String(team.id));
  const inner = `
      <div class="kit-render" data-pending data-team-id="${tid}" data-kit-id="${esc(kit.id)}" style="width:70px;height:70px;background:var(--surface-2);border-radius:8px;flex-shrink:0;"></div>
      <div class="mr-kit-gar">
        <div class="garment-render" data-pending data-team-id="${tid}" data-kit-id="${esc(kit.id)}" data-garment="shorts" data-combo-index="${ci}" style="width:44px;height:33px;background:var(--surface-2);border-radius:6px;"></div>
        <div class="garment-render" data-pending data-team-id="${tid}" data-kit-id="${esc(kit.id)}" data-garment="socks" data-combo-index="${ci}" style="width:44px;height:33px;background:var(--surface-2);border-radius:6px;"></div>
      </div>`;
  return `<div class="mr-kit"><div class="mr-kit-prev">${inner}</div><div class="mr-kit-lbl">${esc(label)}</div></div>`;
}
// Uniforme del árbitro: usa el uniforme de árbitro del torneo si existe; si no, uno TODO NEGRO construido
// sobre la MISMA base del uniforme de jugador. Se dibuja aparte (mrRenderRefKit) porque no es un DB.team.
function mrRefKitBox(){
  return `<div class="mr-kit"><div class="mr-kit-prev">
      <div class="mr-refkit" data-ref-kit style="width:70px;height:70px;background:var(--surface-2);border-radius:8px;flex-shrink:0;"></div>
      <div class="mr-kit-gar">
        <div class="mr-refgar" data-ref-gar="shorts" style="width:44px;height:33px;background:var(--surface-2);border-radius:6px;"></div>
        <div class="mr-refgar" data-ref-gar="socks" style="width:44px;height:33px;background:var(--surface-2);border-radius:6px;"></div>
      </div></div><div class="mr-kit-lbl">Cuerpo arbitral</div></div>`;
}
// Dibuja el uniforme del árbitro (negro por defecto, sobre la base del jugador) en la ventana del informe.
function mrRenderRefKit(){
  try{
    const BK="#161616";
    const rk = (typeof refereeDefaultKit==="function") ? refereeDefaultKit() : null;
    const kit = rk || { category:"arbitro", baseNumber:1, color1:BK, color2:BK, color3:BK, layers:[] };
    const combo = (rk && rk.combinations && rk.combinations[0]) || { shortsBaseNumber:1, shortsColor1:BK, shortsColor2:BK, shortsColor3:BK, shortsLayers:[], socksBaseNumber:1, socksColor1:BK, socksColor2:BK, socksColor3:BK, socksLayers:[] };
    const shirtEl=document.querySelector('#jg-view [data-ref-kit]');
    if(shirtEl && typeof buildKitDataURL==="function"){ buildKitDataURL(kit,320).then(url=>{ if(url) shirtEl.innerHTML=`<img src="${url}" style="width:100%;height:100%;object-fit:contain;">`; }).catch(()=>{}); }
    ["shorts","socks"].forEach(type=>{
      const el=document.querySelector('#jg-view [data-ref-gar="'+type+'"]'); if(!el || typeof buildGarmentDataURL!=="function") return;
      buildGarmentDataURL(type, combo[type+"BaseNumber"]||1, combo[type+"Color1"]||BK, combo[type+"Color2"]||BK, combo[type+"Color3"]||BK, combo[type+"Layers"]||[]).then(url=>{ if(url) el.innerHTML=`<img src="${url}" style="width:100%;height:100%;object-fit:contain;">`; }).catch(()=>{});
    });
  }catch(e){}
}
// Equipo (envoltorio) del que salen los uniformes de árbitro de un partido, según la fuente:
//   1) Si el partido es de un TORNEO → uniformes de árbitro de ese torneo (automático).
//   2) La fuente indicada en la línea de uniformes: Con<CONF> (FIFA/CONCACAF/…) o Tor<TORNEO>.
//   3) Por defecto (partido internacional) → uniformes de árbitro de la FIFA.
//   4) Respaldo → uniformes de árbitro del evento global.
function mrResolveRefTeam(f){
  const has=(w)=>w && (w.kits||[]).length;
  // 1) Torneo automático.
  if(f && !f.friendly && f.competition && typeof competitionByName==="function"){
    const comp=competitionByName(f.competition);
    if(comp && comp.id){ const w=getTeam(refKitsWrapId("comp",comp.id)); if(has(w)) return w; }
  }
  // 2) Fuente de la línea.
  const sel=f&&f.kitSel&&f.kitSel.ref;
  if(sel && sel.code){
    const code=String(sel.code).toUpperCase();
    if(sel.kind==="tour"){
      const comp=(DB.competitions||[]).find(c=>(c.code||"").toUpperCase()===code);
      if(comp && comp.id){ const w=getTeam(refKitsWrapId("comp",comp.id)); if(has(w)) return w; }
    } else if(sel.kind==="fed"){
      // Federación: el código de 3 letras es el PAÍS; se usan los uniformes de árbitro de esa federación.
      const team=(DB.teams||[]).find(t=>(t.fifaCode||"").toUpperCase()===code || (t.iocCode||"").toUpperCase()===code);
      if(team){ const w=getTeam(refKitsWrapId("fed",team.id)); if(has(w)) return w; }
    } else {
      if(/^FIFA$/i.test(sel.code)){ const w=getTeam(refKitsWrapId("fifa","FIFA")); if(has(w)) return w; }
      else { const key=Object.keys(DB.confederations||{}).find(k=>k.toUpperCase()===code); if(key){ const w=getTeam(refKitsWrapId("conf",key)); if(has(w)) return w; } }
    }
  }
  // 3) Default internacional → FIFA.
  const wf=getTeam(refKitsWrapId("fifa","FIFA")); if(has(wf)) return wf;
  // 4) Respaldo → evento global.
  const ev=(typeof REFEREE_KIT_TEAM_ID!=="undefined")?getTeam(REFEREE_KIT_TEAM_ID):null; if(has(ev)) return ev;
  return null;
}
// Resuelve {team, kit, comboIndex} del árbitro para un partido, con el número R<n> de la línea.
function mrResolveRefKit(f){
  const team=mrResolveRefTeam(f); if(!team) return null;
  const kits=(team.kits||[]).filter(k=>k.category==="arbitro"); if(!kits.length) return null;
  const sel=f&&f.kitSel&&f.kitSel.ref; const num=sel?sel.num:null;
  const i=(num!=null && num>=1 && num<=kits.length)?(num-1):0;
  const kit=kits[i]||kits[0];
  return { team, kit, comboIndex:mrComboIndex(kit,null) };
}
// Caja del árbitro: uniforme resuelto (FIFA/confederación/torneo). Si no hay ninguno, el negro por defecto.
function mrRefKitBoxResolved(f){
  const r=mrResolveRefKit(f);
  if(r && r.kit) return mrKitBox(r.team, r.kit, r.comboIndex, "Cuerpo arbitral");
  return mrRefKitBox();   // respaldo negro (se dibuja en mrRenderRefKit)
}
function mrKitsHTML(f, A, B){
  const sel=f&&f.kitSel;
  const dateISO=(f&&f.date)||null;   // la fecha del partido elige la versión por época de cada equipación
  const boxFor=(team, side, label, cat)=>{
    if(!team) return mrKitBox(null,null,0,label);
    const s=sel&&sel[side];
    const num=s?(cat==="portero"?s.porteroNum:s.jugadorNum):null;
    const comboN=s?(cat==="portero"?s.porteroCombo:s.jugadorCombo):null;
    const kit=mrPickKit(team,cat,num,dateISO);
    return mrKitBox(team, kit, mrComboIndex(kit,comboN), label);
  };
  return `<div class="mr-section">
    <div class="mr-h">Uniformes</div>
    <div class="mr-kits">
      ${boxFor(A,"home",teamName(A)+" · jugador","jugador")}
      ${boxFor(A,"home",teamName(A)+" · portero","portero")}
      ${mrRefKitBoxResolved(f)}
      ${boxFor(B,"away",teamName(B)+" · portero","portero")}
      ${boxFor(B,"away",teamName(B)+" · jugador","jugador")}
    </div>
  </div>`;
}
// Contenido completo del informe. La tarjeta de detalle va ARRIBA (centro); debajo, en una fila alineada,
// las canchas (local | visitante) flanquean el rectángulo secundario (goles/rojas) + línea de tiempo +
// estadísticas + uniformes. Bajo cada cancha, la lista de alineación.
function matchReportHTML(f){
  const A=getTeam(f.teamA), B=getTeam(f.teamB);
  const detail=calDetailCardHTML(f, A, {clickable:false, noIncidents:true});   // solo la tarjeta
  const incidents = fxPlayed(f) ? calIncidentsHTML(f, A) : "";                   // rectángulo secundario
  const homeLu=f.lineups&&f.lineups.home, awayLu=f.lineups&&f.lineups.away;
  const side=(team, lu, cls, mirror)=>`<div class="mr-side ${cls}">
      <div class="mr-pcap">${flagImg(team,18)}<span>${esc(teamName(team))}</span>${lu?`<span class="mr-form">${esc(lu.formation)}${lu.formationType?` (${esc(lu.formationType)})`:""}</span>`:""}</div>
      ${mrPitchHTML(lu)}
      ${mrLineupListHTML(lu, f, mirror)}
    </div>`;
  return `<div class="mr-body"><div class="mr-grid">
      <div class="mr-topcard">${detail}</div>
      ${side(A, homeLu, "mr-side-l")}
      <div class="mr-center">
        ${incidents?`<div class="mr-incidents">${incidents}</div>`:""}
        ${mrTimelineHTML(f,A,B)}
        ${f.stats?mrStatsHTML(f,A,B):""}
        ${mrKitsHTML(f,A,B)}
      </div>
      ${side(B, awayLu, "mr-side-r", true)}
    </div></div>`;
}
// ¿La entrada actual del historial es un informe?
function navIsReport(){ try{ return !!(navHistory[navIndex] && navHistory[navIndex].report); }catch(e){ return false; } }
// Empuja una entrada de informe al historial (para que ← → y "atrás" lo recorran como una pantalla más).
function pushReportHistory(fxId){
  try{
    if(typeof navHistory==="undefined") return;
    if(typeof saveScrollToCurrent==="function") saveScrollToCurrent();
    navHistory = navHistory.slice(0, navIndex+1);
    navHistory.push({ report:fxId });
    if(typeof MAX_NAV_HISTORY==="number" && navHistory.length>MAX_NAV_HISTORY) navHistory = navHistory.slice(navHistory.length-MAX_NAV_HISTORY);
    navIndex = navHistory.length-1;
    if(typeof renderNavButtons==="function") renderNavButtons();
  }catch(e){}
}
// Dibuja el informe como una PANTALLA normal dentro de #jg-view (NO como capa encima). Así el buscador,
// las pestañas superiores y Continuar siguen funcionando y la pantalla no queda "encima" de lo demás.
function mrShow(fxId){
  const f=(DB.fixtures||[]).find(x=>x.id===fxId); if(!f) return;
  mount();
  JUEGO.screen="informe-partido"; JUEGO.active=true; JUEGO.reportFx=fxId;
  const v=document.getElementById("view"); if(v) v.hidden=true;
  const gv=document.getElementById("jg-view"); if(!gv) return;
  gv.hidden=false; gv.classList.remove("jg-fixed");
  document.body.classList.add("mr-fs");   // el informe cubre también la barra lateral (pero sigue siendo pantalla normal)
  gv.innerHTML=`<div class="mr-screen"><button class="mr-x" data-mr-close title="Cerrar">×</button>${matchReportHTML(f)}</div>`;
  try{ if(typeof clearTopTabActive==="function") clearTopTabActive(); }catch(e){}
  document.querySelectorAll("#jg-sidebar .jg-item").forEach(b=>b.classList.remove("on"));
  window.scrollTo(0,0);
  try{ if(typeof renderKitPreviews==="function") renderKitPreviews(); }catch(e){}   // previsualizaciones de uniformes
  try{ if(typeof mrRenderRefKit==="function") mrRenderRefKit(); }catch(e){}          // uniforme del árbitro (negro)
}
// El informe ya no es una capa: al navegar a otra pantalla se reemplaza el contenido de #jg-view solo.
function mrHide(){ JUEGO.reportFx=null; try{ document.body.classList.remove("mr-fs"); }catch(e){} }
// Cerrar con la X / Esc: equivale a "atrás".
function mrDismiss(){ if(typeof navBack==="function") navBack(); }
// Abrir el informe (acción del usuario): empuja al historial y muestra.
function openMatchReport(fxId){ if(!(DB.fixtures||[]).some(x=>x.id===fxId)) return; pushReportHistory(fxId); mrShow(fxId); }
function closeMatchReport(){ mrDismiss(); }

// Celda enriquecida de la cuadrícula: arriba el torneo/amistoso; abajo [escudo] Equipo - Equipo [escudo].
function calGridEventHTML(f, t){
  const home=(f.teamA===t.id); const o=oppOf(f); const A=home?t:o, B=home?o:t;
  const mid=fxPlayed(f)?`${f.scoreA}-${f.scoreB}`:"-";
  return `<div class="jg-gev">
    <div class="ge-top">${calTourChipHTML(f,true)}</div>
    <div class="ge-bot">${calMiniCrest(A,true)}<span class="ge-nm">${calTeamLink(A)} ${mid} ${calTeamLink(B)}</span>${calMiniCrest(B,true)}</div>
  </div>`;
}
// Fija --jg-topbar-h con la altura real de la barra superior fija, para anclar el detalle debajo de ella.
let jgTopbarBound=false;
function updateTopbarH(){
  try{ const tb=document.querySelector(".topbar"); if(tb) document.documentElement.style.setProperty("--jg-topbar-h", tb.offsetHeight+"px"); }catch(e){}
}
function bindTopbarH(){ if(jgTopbarBound) return; jgTopbarBound=true; try{ window.addEventListener("resize", updateTopbarH); }catch(e){} }

function renderCalBody(){
  const b=document.getElementById("jg-calbody"); if(!b) return;
  updateTopbarH(); bindTopbarH();
  const t=team(); let fx=teamFixtures();
  if(calView==="lista"){
    if(!fx.length){ b.innerHTML=`<div class="empty"><div class="jg-empic">${jgIco("calendar",30)}</div><h3>Calendario no generado</h3><p>Aún no se han generado los partidos. Se conectará con el calendario oficial del torneo.</p></div>`; return; }
    // Orden descendente: del más reciente al más lejano.
    fx=fx.slice().sort((a,c)=> String((c.date||"")+(c.time||"")).localeCompare(String((a.date||"")+(a.time||""))));
    // Por defecto se muestra SIEMPRE el siguiente partido.
    if(!calSelId || !fx.some(f=>f.id===calSelId)){ const nf=nextFixture(); calSelId=(nf && fx.some(f=>f.id===nf.id))?nf.id:fx[0].id; }
    const sel=fx.find(f=>f.id===calSelId)||fx[0];
    b.innerHTML=`<div class="jg-cal-split">
      <div class="jg-cal-listcol"><div class="tbl-wrap" style="padding:4px 6px;">${(()=>{ let lastYear=null; return fx.map(f=>{ const y=(f.date||"").slice(0,4); let sep=""; if(y && y!==lastYear){ lastYear=y; sep=`<div class="jg-cal-year">${y}</div>`; } return sep+calMatchRowHTML(f,t); }).join(""); })()}</div></div>
      <div class="jg-cal-detailcol">${calDetailCardHTML(sel,t)}</div>
    </div>`;
    jgFitTourNames(b);
  }else{
    const months=calFixtureMonths();
    if(!months.length){ b.innerHTML=`<div class="empty"><div class="jg-empic">${jgIco("calendar",30)}</div><h3>Calendario no generado</h3><p>Aún no se han generado los partidos.</p></div>`; return; }
    if(calMonthIdx<0) calMonthIdx=0; if(calMonthIdx>months.length-1) calMonthIdx=months.length-1;
    const cur=months[calMonthIdx];
    const ev={};
    fx.forEach(f=>{ if(f.date && +f.date.slice(0,4)===cur.y && +f.date.slice(5,7)===cur.m){ const d=parseInt(f.date.slice(8,10),10); const o2=oppOf(f); const vpTip=(()=>{ try{ const vp=venueParts(f); return vp&&vp.name?` · ${vp.name}`:(f.venue?` · ${f.venue}`:""); }catch(e){ return f.venue?` · ${f.venue}`:""; } })(); const tip=(f.date?fmtDayMon(f.date)+" · ":"")+teamName(f.teamA===t.id?t:o2)+(fxPlayed(f)?` ${f.scoreA}-${f.scoreB} `:" - ")+teamName(f.teamB===t.id?t:o2)+vpTip; (ev[d]=ev[d]||[]).push(["match", calGridEventHTML(f,t), tip, "", true]); } });
    const today=(cur.y===CAL_GAME_MONTH.y&&cur.m===CAL_GAME_MONTH.m)?1:null;
    const nav=`<div class="jg-calnav"><button class="jg-calnavb" data-calnav="prev" ${calMonthIdx<=0?"disabled":""}>‹</button><span class="jg-calmes">${CAL_MES_LARGO[cur.m-1]} ${cur.y}</span><button class="jg-calnavb" data-calnav="next" ${calMonthIdx>=months.length-1?"disabled":""}>›</button></div>`;
    b.innerHTML=nav+monthGridFor(cur.y, cur.m, ev, today)+`<div class="jg-legend"><span><i style="background:var(--indigo);"></i>Partido</span></div>`;
  }
}

