/* Fechas cortas */
const MESES=["ENE","FEB","MAR","ABR","MAY","JUN","JUL","AGO","SEP","OCT","NOV","DIC"];
function monShort(iso){ const m=parseInt(iso.slice(5,7),10); return MESES[m-1]||"JUN"; }
function fmtDayMon(iso){ const d=parseInt(iso.slice(8,10),10); return d+" "+monShort(iso)+" 2026"; }

/* ============================================================
   Editor de la Copa del Mundo: tabla editable "Expectativa de la prensa".
   Se agrega al detalle del evento (sin tocar funciones/evento.js) envolviendo
   renderEventoDetail; los cambios se guardan con persist().
   ============================================================ */
function pressExpectationEditorHTML(){
  const pe=ensurePE();
  const teams=(DB.teams||[]).filter(t=>t.group && String(t.group).trim()).slice()
    .sort((a,b)=> String(a.group||"").localeCompare(String(b.group||"")) || String(a.commonName||"").localeCompare(String(b.commonName||""),'es'));
  return `
  <div class="section-title"><h2>Expectativa de la prensa</h2><span class="hint">Hasta qué ronda espera la prensa que llegue cada selección</span></div>
  <div class="tbl-wrap"><table><thead><tr><th style="width:52px;">Grupo</th><th>Selección</th><th style="width:230px;">Expectativa</th></tr></thead><tbody>
  ${teams.map(t=>`<tr><td class="mono" style="color:var(--muted);">${esc(t.group||"")}</td><td style="font-weight:600;">${esc(t.commonName||t.name)}</td><td><select class="jg-pe-select" data-team="${t.id}">${PE_STAGES.map(s=>`<option value="${s[0]}" ${pe[t.id]===s[0]?"selected":""}>${s[1]}</option>`).join("")}</select></td></tr>`).join("")}
  </tbody></table></div>`;
}
if(typeof renderEventoDetail==="function" && !renderEventoDetail.__jgWrapped){
  const _origRenderEventoDetail = renderEventoDetail;
  renderEventoDetail = function(){ return _origRenderEventoDetail.apply(this, arguments) + pressExpectationEditorHTML(); };
  renderEventoDetail.__jgWrapped = true;
}
document.addEventListener("change", function(e){
  const sel = e.target && e.target.closest ? e.target.closest(".jg-pe-select") : null;
  if(!sel) return;
  ensurePE();
  DB.event.pressExpectations[sel.dataset.team] = sel.value;
  try{ if(typeof persist==="function") persist(); }catch(err){}
});

